"""Generic sandbox environment — provides execute_bash + str_replace_editor tools.

Modified from https://github.com/llm-in-sandbox/llm-in-sandbox
"""

import contextlib
import shlex
from dataclasses import dataclass
from typing import Any, ClassVar

from openenv.core.env_server.types import State

from open_instruct import logger_utils

from .backends import SandboxBackend, create_backend
from .base import BaseEnvConfig, EnvCall, RLEnvironment, StepResult
from .tools.utils import coerce_args

logger = logger_utils.setup_logger(__name__)


class _EditorError(Exception):
    """Raised by editor sub-commands to signal a user-visible error."""


_BASH_WRAPPER = r"""#!/bin/bash
set -a; source /tmp/.sandbox_env 2>/dev/null; set +a
cd "$(cat /tmp/.sandbox_cwd 2>/dev/null || echo /testbed)" 2>/dev/null
eval "$1"
_exit_code=$?
export -p > /tmp/.sandbox_env
pwd > /tmp/.sandbox_cwd
exit $_exit_code
"""

_EXECUTE_BASH_TOOL: dict[str, Any] = {
    "type": "function",
    "function": {
        "name": "execute_bash",
        "description": (
            "Execute a bash command in the terminal.\n"
            "* Long running commands: Wrap with `timeout`, e.g., `timeout 10 <command>`.\n"
            "* Interactive: Not possible. Use `yes`/`no`, etc. as appropriate.\n"
            "* Output: May be truncated. Use `head`/`tail`/`grep` to filter."
        ),
        "parameters": {
            "type": "object",
            "properties": {"command": {"type": "string", "description": "The bash command to execute."}},
            "required": ["command"],
        },
    },
}

_STR_REPLACE_EDITOR_TOOL: dict[str, Any] = {
    "type": "function",
    "function": {
        "name": "str_replace_editor",
        "description": (
            "Custom editing tool for viewing, creating, and editing files.\n"
            "* State is persistent across command calls and discussions.\n"
            "* `view` for reading files/directories, `create` for new files,\n"
            "  `str_replace` for editing, `insert` for adding lines."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "command": {
                    "type": "string",
                    "enum": ["view", "create", "str_replace", "insert"],
                    "description": "The editor command to run.",
                },
                "path": {"type": "string", "description": "Absolute path to file or directory."},
                "file_text": {
                    "type": "string",
                    "description": "Required for `create`. The full content of the new file.",
                },
                "old_str": {
                    "type": "string",
                    "description": "Required for `str_replace`. The exact string to replace (must appear exactly once).",
                },
                "new_str": {"type": "string", "description": "Required for `str_replace`/`insert`. The new string."},
                "insert_line": {
                    "type": "integer",
                    "description": "Required for `insert`. Line number after which to insert `new_str`.",
                },
                "view_range": {
                    "type": "array",
                    "items": {"type": "integer"},
                    "description": "Optional for `view`. Two-element [start, end] line range.",
                },
            },
            "required": ["command", "path"],
        },
    },
}


def _truncate_output(text: str, num_lines: int = 40) -> str:
    """Truncate long output keeping first and last *num_lines* lines."""
    lines = text.splitlines()
    if len(lines) <= 2 * num_lines:
        return text
    top = "\n".join(lines[:num_lines])
    bottom = "\n".join(lines[-num_lines:])
    divider = "-" * 50
    return f"{top}\n{divider}\n<Observation truncated in middle for saving context>\n{divider}\n{bottom}"


class GenericSandboxEnv(RLEnvironment):
    """Generic sandbox environment with execute_bash and str_replace_editor tools.

    Provides two tools:
    * ``execute_bash`` — stateful bash (env vars, cwd persist between calls)
    * ``str_replace_editor`` — file viewer/editor (view/create/str_replace/insert)
    """

    config_name = "generic_sandbox"
    _tool_definitions = (_EXECUTE_BASH_TOOL, _STR_REPLACE_EDITOR_TOOL)

    def __init__(
        self, backend: str = "docker", write_prompt_file: bool = False, timeout: int = 300, **backend_kwargs: Any
    ):
        self._backend_type = backend
        self._write_prompt_file = write_prompt_file
        self._timeout = timeout
        self._penalty = backend_kwargs.pop("penalty", -0.05)
        backend_kwargs.pop("call_name", None)
        self._backend_kwargs = backend_kwargs
        self._backend: SandboxBackend | None = None
        self._step_count = 0
        self._task_prompt: str | None = None

    @classmethod
    def get_tool_definitions(cls) -> list[dict]:
        return list(cls._tool_definitions)

    async def reset(self, **kwargs: Any) -> tuple[StepResult, list[dict]]:
        last_error = None
        for attempt in range(3):
            try:
                return self._do_reset(**kwargs)
            except Exception as e:
                last_error = e
                logger.warning(f"GenericSandboxEnv.reset attempt {attempt + 1} failed: {e}. Retrying...")
                if self._backend is not None:
                    with contextlib.suppress(Exception):
                        self._backend.close()
                    self._backend = None
        if last_error is not None:
            raise RuntimeError(f"Reset failed after 3 attempts: {last_error}") from last_error
        else:
            raise RuntimeError("Reset failed without capturing an error.")

    def _do_reset(self, **kwargs: Any) -> tuple[StepResult, list[dict]]:
        task_prompt = kwargs.get("task_prompt")
        if self._backend is not None:
            self._backend.close()
        bkwargs = dict(self._backend_kwargs)
        bkwargs.setdefault("timeout", self._timeout)
        self._backend = create_backend(self._backend_type, **bkwargs)
        self._backend.start()
        self._step_count = 0
        self._task_prompt = task_prompt

        self._backend.run_command("mkdir -p /testbed/input /testbed/output")
        if self._backend.run_command("which git").exit_code == 0:
            git_result = self._backend.run_command(
                "cd /testbed && git init && git config user.email 'tulu@example.com' && git config user.name 'Tulu'"
            )
            if git_result.exit_code != 0:
                logger.warning(f"git init/config failed (exit {git_result.exit_code}): {git_result.stderr.strip()}")
        self._backend.write_file("/tmp/.sandbox_bash_wrapper.sh", _BASH_WRAPPER)
        self._backend.run_command("chmod +x /tmp/.sandbox_bash_wrapper.sh")
        self._backend.run_command("echo /testbed > /tmp/.sandbox_cwd")

        if self._write_prompt_file and task_prompt:
            self._backend.write_file("/root/prompt.txt", task_prompt)

        observation = "Sandbox ready."
        if task_prompt:
            observation = f"[Task: {task_prompt}] {observation}"

        return (
            StepResult(result=observation, metadata={"task_prompt": task_prompt, "backend": self._backend_type}),
            list(self._tool_definitions),
        )

    async def step(self, call: EnvCall) -> StepResult:
        if self._backend is None:
            raise RuntimeError("Environment not reset. Call reset() first.")

        self._step_count += 1

        if call.name == "execute_bash":
            args = coerce_args(_EXECUTE_BASH_TOOL["function"]["parameters"], call.args)
            return self._execute_bash(args)
        elif call.name == "str_replace_editor":
            args = coerce_args(_STR_REPLACE_EDITOR_TOOL["function"]["parameters"], call.args)
            return self._execute_editor(args)
        else:
            return StepResult(
                result=f"Error: Unknown tool '{call.name}'. Available: execute_bash, str_replace_editor",
                reward=self._penalty,
            )

    def _execute_bash(self, args: dict) -> StepResult:
        assert self._backend is not None
        command = args.get("command", "")
        if not command:
            return StepResult(result="Error: 'command' parameter is required for execute_bash.", reward=self._penalty)

        result = self._backend.run_command(f"bash /tmp/.sandbox_bash_wrapper.sh {shlex.quote(command)}")

        stdout = _truncate_output(result.stdout) if result.stdout else ""
        stderr = _truncate_output(result.stderr) if result.stderr else ""

        observation = (
            f"Exit code: {result.exit_code}\n"
            f"Execution output of [execute_bash]:\n"
            f"[STDOUT]\n{stdout}\n"
            f"[STDERR]\n{stderr}"
        )

        reward = 0.0 if result.exit_code == 0 else self._penalty
        return StepResult(result=observation, reward=reward, metadata={"exit_code": result.exit_code})

    def _execute_editor(self, args: dict) -> StepResult:
        assert self._backend is not None
        command = args.get("command", "")
        path = args.get("path", "")

        if not command:
            return self._editor_error("'command' parameter is required.")
        if not path:
            return self._editor_error("'path' parameter is required.")

        try:
            if command == "view":
                output = self._editor_view(path, args.get("view_range"))
            elif command == "create":
                output = self._editor_create(path, args.get("file_text"))
            elif command == "str_replace":
                output = self._editor_str_replace(path, args.get("old_str"), args.get("new_str"))
            elif command == "insert":
                output = self._editor_insert(path, args.get("insert_line"), args.get("new_str"))
            else:
                return self._editor_error(f"Unknown command '{command}'. Use view/create/str_replace/insert.")
        except (_EditorError, FileNotFoundError) as exc:
            return self._editor_error(str(exc))

        return StepResult(result=f"Execution output of [str_replace_editor]:\n{output}")

    def _editor_view(self, path: str, view_range: list[int] | None = None) -> str:
        assert self._backend is not None
        check = self._backend.run_command(f"test -d {shlex.quote(path)}")
        is_dir = check.exit_code == 0

        if is_dir:
            result = self._backend.run_command(
                f'find {shlex.quote(path)} -maxdepth 2 -not -path "*/.*" | sort | head -100'
            )
            return _truncate_output(result.stdout)

        if view_range and len(view_range) == 2:
            start, end = view_range
            cmd = f"cat -n {shlex.quote(path)} | sed -n '{start},{end}p'"
        else:
            cmd = f"cat -n {shlex.quote(path)}"

        result = self._backend.run_command(cmd)
        if result.exit_code != 0:
            raise _EditorError(f"Failed to view '{path}': {result.stderr or result.stdout}")
        return _truncate_output(result.stdout)

    def _editor_create(self, path: str, file_text: str | None) -> str:
        assert self._backend is not None
        if file_text is None:
            raise _EditorError("'file_text' parameter is required for create.")

        if self._backend.run_command(f"test -d {shlex.quote(path)}").exit_code == 0:
            raise _EditorError(f"'{path}' is a directory. Cannot create a file with the same name.")
        if self._backend.run_command(f"test -e {shlex.quote(path)}").exit_code == 0:
            raise _EditorError(f"File '{path}' already exists. Use str_replace to edit.")

        parent = "/".join(path.rsplit("/", 1)[:-1]) or "/"
        self._backend.run_command(f"mkdir -p {shlex.quote(parent)}")
        self._backend.write_file(path, file_text)
        return f"File created successfully at: {path}"

    def _editor_str_replace(self, path: str, old_str: str | None, new_str: str | None) -> str:
        assert self._backend is not None
        if old_str is None:
            raise _EditorError("'old_str' parameter is required for str_replace.")
        if new_str is None:
            raise _EditorError("'new_str' parameter is required for str_replace.")

        content = self._backend.read_file(path)
        if isinstance(content, bytes):
            content = content.decode("utf-8", errors="replace")

        count = content.count(old_str)
        if count == 0:
            raise _EditorError(f"old_str not found in {path}. Make sure it matches exactly.")
        if count > 1:
            raise _EditorError(f"old_str found {count} times in {path}. It must appear exactly once.")

        new_content = content.replace(old_str, new_str, 1)
        self._backend.write_file(path, new_content)
        return f"The file {path} has been edited. Review the changes with `view`."

    def _editor_insert(self, path: str, insert_line: int | None, new_str: str | None) -> str:
        assert self._backend is not None
        if insert_line is None:
            raise _EditorError("'insert_line' parameter is required for insert.")
        if new_str is None:
            raise _EditorError("'new_str' parameter is required for insert.")

        content = self._backend.read_file(path)
        if isinstance(content, bytes):
            content = content.decode("utf-8", errors="replace")

        lines = content.splitlines(keepends=True)
        idx = max(0, min(insert_line, len(lines)))
        insert_text = new_str if new_str.endswith("\n") else new_str + "\n"
        insert_lines = insert_text.splitlines(keepends=True)
        new_lines = lines[:idx] + insert_lines + lines[idx:]
        self._backend.write_file(path, "".join(new_lines))
        return f"The file {path} has been edited. Review the changes with `view`."

    def _editor_error(self, message: str) -> StepResult:
        return StepResult(result=f"Execution output of [str_replace_editor]:\nERROR: {message}", reward=self._penalty)

    def get_metrics(self) -> dict[str, float]:
        return {"step_count": float(self._step_count)}

    def state(self) -> State:
        return State(episode_id=self._task_prompt, step_count=self._step_count)

    async def close(self) -> None:
        if self._backend is not None:
            self._backend.close()
            self._backend = None

    async def shutdown(self) -> None:
        """Clean up backend on actor shutdown."""
        await self.close()


@dataclass
class GenericSandboxEnvConfig(BaseEnvConfig):
    """Configuration for GenericSandboxEnv."""

    tool_class: ClassVar[type[RLEnvironment]] = GenericSandboxEnv
    backend: str = "docker"
    image: str = "python:3.12-slim"
    mem_limit: str = "4g"
    penalty: float = -0.05
    write_prompt_file: bool = False
    timeout: int = 300

# Client-side code ported from code-execution-service revision 103ca279b35e8e81d118947f82b72c22676c6540.
"""Client for the code execution service.

    client = CodeExecutionClient("https://<function-url>", token=os.environ["CODE_EXECUTION_TOKEN"])
    result = client.execute("assert", program, ["assert add(1, 2) == 3"], per_test_seconds=1.0)
    result.all_passed  # True/False
    result.outcomes    # [Outcome(status="passed", runtime=..., detail=None), ...]

Service faults (429, 5xx, transport errors, timeouts) raise ServiceError after retries so the caller
must mask the sample or abort training; they are never silently turned into
test failures. Other client errors (4xx) raise ClientError immediately.
"""

import base64
import dataclasses
import json
import math
import random
import time
import uuid
import zlib

import requests

from open_instruct.code_utils.execution_client import livecodebench, protocol

__all__ = ["ClientError", "CodeExecutionClient", "ExecuteResult", "Outcome", "ServiceError"]

RETRY_STATUSES = {429, 500, 502, 503, 504}


def _number(value, minimum=0):
    try:
        return type(value) in (int, float) and math.isfinite(value) and value >= minimum
    except OverflowError:
        return False


def _validate_v1(data, count):
    if not isinstance(data, dict):
        raise ValueError("response must be an object")
    results, runtimes = data.get("results"), data.get("runtimes")
    if not isinstance(results, list) or not isinstance(runtimes, list):
        raise ValueError("results and runtimes must be lists")
    if len(results) != count or len(runtimes) != count:
        raise ValueError("response test count does not match request")
    for result, runtime in zip(results, runtimes, strict=True):
        if type(result) not in (int, float) or result not in (0, 1):
            raise ValueError("results must contain only numeric zero or one")
        if not _number(runtime, -1) or (runtime < 0 and runtime != -1) or (result == 1 and runtime < 0):
            raise ValueError("invalid test runtime")


def _validate_v2(data, count):
    if not isinstance(data, dict) or not isinstance(data.get("outcomes"), list):
        raise ValueError("response must contain outcomes")
    if len(data["outcomes"]) != count:
        raise ValueError("response test count does not match request")
    if not _number(data.get("wall_seconds")) or not isinstance(data.get("exit"), str):
        raise ValueError("invalid execution metadata")
    if data["exit"] in ("wall_timeout", "runner_error") or data.get("runner_error"):
        raise ValueError("execution was incomplete")
    for item in data["outcomes"]:
        if not isinstance(item, dict) or item.get("status") not in ("passed", "failed", "timeout", "error", "crashed"):
            raise ValueError("invalid or unexecuted test outcome")
        runtime, detail = item.get("runtime"), item.get("detail")
        if (runtime is not None and not _number(runtime)) or (item["status"] == "passed" and runtime is None):
            raise ValueError("invalid test runtime")
        if detail is not None and not isinstance(detail, str):
            raise ValueError("invalid test detail")


class ServiceError(RuntimeError):
    def __init__(self, message, status=None, attempts=0, request_id=None):
        super().__init__(message)
        self.status, self.attempts, self.request_id = status, attempts, request_id


class ClientError(ValueError):
    def __init__(self, message, status, request_id=None):
        super().__init__(message)
        self.status, self.request_id = status, request_id


@dataclasses.dataclass(frozen=True)
class Outcome:
    status: str
    runtime: float | None
    detail: str | None

    @property
    def passed(self):
        return self.status == "passed"


@dataclasses.dataclass(frozen=True)
class ExecuteResult:
    outcomes: list[Outcome]
    wall_seconds: float
    exit: str
    request_id: str
    attempts: int
    request_ids: tuple[str, ...] = ()

    @property
    def all_passed(self):
        return bool(self.outcomes) and all(outcome.passed for outcome in self.outcomes)

    @property
    def pass_fraction(self):
        return sum(outcome.passed for outcome in self.outcomes) / len(self.outcomes) if self.outcomes else 0.0


class CodeExecutionClient:
    def __init__(
        self,
        base_url,
        token=None,
        *,
        timeout=30.0,
        retries=3,
        backoff=1.0,
        session=None,
        max_request_seconds=20.0,
        max_request_bytes=5 << 20,
        max_batch_tests=16,
        total_timeout=300.0,
        expected_source_sha256=None,
        cancel_event=None,
    ):
        for name, value in (
            ("timeout", timeout),
            ("total_timeout", total_timeout),
            ("max_request_seconds", max_request_seconds),
        ):
            if not _number(value) or value <= 0:
                raise ValueError(f"{name} must be finite and positive")
        if type(retries) is not int or retries < 0 or not _number(backoff):
            raise ValueError("retries and backoff must be nonnegative")
        if type(max_request_bytes) is not int or max_request_bytes <= 0:
            raise ValueError("max_request_bytes must be positive")
        if type(max_batch_tests) is not int or not 1 <= max_batch_tests <= protocol.MAX_TESTS:
            raise ValueError("invalid max_batch_tests")
        self.base_url = base_url.rstrip("/")
        self.token = token
        self.timeout = timeout
        self.retries = retries
        self.backoff = backoff
        self.session = session or requests.Session()
        self.max_request_seconds = max_request_seconds
        self.max_request_bytes = max_request_bytes
        self.max_batch_tests = max_batch_tests
        self.total_timeout = total_timeout
        self.expected_source_sha256 = expected_source_sha256
        self.cancel_event = cancel_event

    def _check_cancelled(self, attempts=0, request_id=None):
        if self.cancel_event is not None and self.cancel_event.is_set():
            raise ServiceError("code grading cancelled", attempts=attempts, request_id=request_id)

    def _safe_error(self, value):
        message = str(value)
        return message.replace(self.token, "<redacted>") if self.token else message

    def _headers(self, request_id):
        headers = {"Content-Type": "application/json", "X-Request-Id": request_id}
        if self.token:
            headers["Authorization"] = f"Bearer {self.token}"
        return headers

    def _post(self, path, payload, validate, deadline):
        request_id = uuid.uuid4().hex
        last_error = None
        for attempt in range(1, self.retries + 2):
            self._check_cancelled(attempt - 1, request_id)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise ServiceError(
                    "complete-test request deadline exceeded", attempts=attempt - 1, request_id=request_id
                )
            try:
                response = self.session.post(
                    self.base_url + path,
                    json=payload,
                    headers=self._headers(request_id),
                    timeout=min(self.timeout, remaining),
                )
            except requests.RequestException as exc:
                last_error = ServiceError(
                    f"{type(exc).__name__}: {self._safe_error(exc)}", attempts=attempt, request_id=request_id
                )
            else:
                self._check_cancelled(attempt, request_id)
                if response.status_code == 200:
                    try:
                        required = payload.get("required_comparisons", [])
                        if required and not set(required) <= set(
                            response.headers.get("X-Service-Comparisons", "").split(",")
                        ):
                            raise ValueError("execution service does not support the dataset's output comparison")
                        if (
                            self.expected_source_sha256
                            and response.headers.get("X-Service-Source-Sha256") != self.expected_source_sha256
                        ):
                            raise ValueError("execution service source fingerprint does not match the pinned revision")
                        data = response.json()
                        validate(data)
                    except (ValueError, TypeError, KeyError) as exc:
                        last_error = ServiceError(
                            f"invalid grading response: {exc}", response.status_code, attempt, request_id
                        )
                    else:
                        if time.monotonic() >= deadline:
                            raise ServiceError(
                                "complete-test request deadline exceeded", attempts=attempt, request_id=request_id
                            )
                        return data, request_id, attempt
                elif response.status_code == 429 or response.status_code >= 500 or response.status_code < 400:
                    last_error = ServiceError(
                        f"HTTP {response.status_code}: {self._safe_error(response.text)[:300]}",
                        response.status_code,
                        attempt,
                        request_id,
                    )
                else:
                    raise ClientError(
                        f"HTTP {response.status_code}: {self._safe_error(response.text)[:300]}",
                        response.status_code,
                        request_id,
                    )
            if attempt <= self.retries:
                self._check_cancelled(attempt, request_id)
                remaining = max(0, deadline - time.monotonic())
                # Full jitter prevents synchronized callers from retrying in lockstep.
                delay = random.uniform(0, min(self.backoff * 2 ** (attempt - 1), remaining))
                if self.cancel_event is None:
                    time.sleep(delay)
                elif self.cancel_event.wait(delay):
                    self._check_cancelled(attempt, request_id)
        # Nonnegative retries guarantee an attempt; every failed attempt sets an error.
        assert last_error is not None
        raise last_error

    def _batches(self, mode, program, tests, seconds, version, language="python", fresh_process_per_test=False):
        try:
            tests = protocol.decode_tests(tests)
            protocol.validate_tests(mode, tests)
            if not isinstance(program, str):
                raise protocol.BadRequest("program must be a string")
            if type(fresh_process_per_test) is not bool:
                raise protocol.BadRequest("fresh_process_per_test must be a boolean")
            seconds = protocol.clamp_per_test_seconds(seconds)
        except protocol.BadRequest as exc:
            raise ClientError(str(exc), 400) from exc
        # Reserve startup/cleanup and per-interpreter overhead below the gateway
        # deadline. Preflight every batch before sending any requests.
        count = min(self.max_batch_tests, int((self.max_request_seconds - 2) / (seconds + 0.1)))
        if count < 1:
            raise ClientError("per-test limit does not fit the configured request time budget", 400)

        def payload_for(batch):
            required = (
                sorted({test.get("comparison", "exact") for test in batch} - {"exact"}) if mode == "stdio" else []
            )
            capability = {"required_comparisons": required} if required else {}
            if version == "v1":
                return {
                    **capability,
                    "program": program,
                    "tests": batch,
                    "max_execution_time": seconds,
                    "fresh_process_per_test": fresh_process_per_test,
                }
            return {
                **capability,
                "language": language,
                "mode": mode,
                "program": program,
                "tests": batch,
                "limits": {"per_test_seconds": seconds},
                "fresh_process_per_test": fresh_process_per_test,
            }

        def fit(batch):
            payload = payload_for(batch)
            raw = json.dumps(batch, allow_nan=False).encode()
            if len(raw) > protocol.MAX_DECODED_TEST_BYTES:
                if len(batch) <= 1:
                    raise ClientError("one test exceeds decoded size limit", 413)
            else:
                if len(json.dumps(payload, allow_nan=False).encode()) <= self.max_request_bytes:
                    return [(payload, len(batch))]
                payload["tests"] = {"encoding": "zlib+json", "data": base64.b64encode(zlib.compress(raw)).decode()}
                if len(json.dumps(payload, allow_nan=False).encode()) <= self.max_request_bytes:
                    return [(payload, len(batch))]
            if len(batch) <= 1:
                raise ClientError("program and one test exceed request size limit even after compression", 413)
            middle = len(batch) // 2
            return fit(batch[:middle]) + fit(batch[middle:])

        batches = []
        for start in range(0, len(tests), count):
            batches.extend(fit(tests[start : start + count]))
        if not tests:
            batches = fit([])
        return batches

    def health(self):
        response = self.session.get(self.base_url + "/health", timeout=self.timeout)
        response.raise_for_status()
        return response.json()

    def execute_livecodebench(self, program, inputs, outputs, *, fn_name=None, **kwargs):
        """Execute every LiveCodeBench input/output pair; optional fn_name selects call tests."""
        mode, tests = livecodebench.prepare_tests(inputs, outputs, fn_name)
        return self.execute(mode, program, tests, **kwargs)

    def execute(self, mode, program, tests, *, per_test_seconds=1.0, language="python", fresh_process_per_test=False):
        deadline = time.monotonic() + self.total_timeout
        batches = self._batches(mode, program, tests, per_test_seconds, "v2", language, fresh_process_per_test)
        outcomes, ids, attempts, wall, exit_kind = [], [], 0, 0.0, "ok"
        for payload, count in batches:
            data, request_id, used = self._post(
                "/v2/execute", payload, lambda data, count=count: _validate_v2(data, count), deadline
            )
            outcomes.extend(
                Outcome(item["status"], item.get("runtime"), item.get("detail")) for item in data["outcomes"]
            )
            ids.append(request_id)
            attempts += used
            wall += data["wall_seconds"]
            if exit_kind == "ok":
                exit_kind = data["exit"]
        return ExecuteResult(outcomes, wall, exit_kind, ids[-1], attempts, tuple(ids))

    # v1-compatible helpers, same shapes the previous service returned.
    def test_program(self, program, tests, max_execution_time=1.0, *, fresh_process_per_test=False):
        return self._v1("assert", program, tests, max_execution_time, fresh_process_per_test)

    def test_program_stdio(self, program, tests, max_execution_time=1.0, *, fresh_process_per_test=False):
        return self._v1("stdio", program, tests, max_execution_time, fresh_process_per_test)

    def _v1(self, mode, program, tests, seconds, fresh_process_per_test=False):
        deadline = time.monotonic() + self.total_timeout
        batches = self._batches(mode, program, tests, seconds, "v1", fresh_process_per_test=fresh_process_per_test)
        results, runtimes = [], []
        for payload, count in batches:
            data, _, _ = self._post(
                "/test_program" if mode == "assert" else "/test_program_stdio",
                payload,
                lambda data, count=count: _validate_v1(data, count),
                deadline,
            )
            results.extend(data["results"])
            runtimes.extend(data["runtimes"])
        return results, runtimes

