        return self.inputs.split(b"\n")[0] + b"\n"


def clean_if_name(code: str) -> str:
    try:
        astree = ast.parse(code)
        last_block = astree.body[-1]
        if isinstance(last_block, ast.If):
            condition = last_block.test
            if ast.unparse(condition).strip() == "__name__ == '__main__'":
                code = ast.unparse(astree.body[:-1]) + "\n" + ast.unparse(last_block.body)  # type: ignore
    except Exception:
        pass

    return code


def make_function(code: str) -> str:
    try:
        import_stmts = []
        all_other_stmts = []
        astree = ast.parse(code)
        for stmt in astree.body:
            if isinstance(stmt, ast.Import | ast.ImportFrom):
                import_stmts.append(stmt)
            else:
                all_other_stmts.append(stmt)

        function_ast = ast.FunctionDef(
            name="wrapped_function",
            args=ast.arguments(posonlyargs=[], args=[], kwonlyargs=[], kw_defaults=[], defaults=[]),
            body=all_other_stmts,
            decorator_list=[],
            lineno=-1,
            type_params=[],
        )
        main_code = (
            import_string
            + "\n"
            + ast.unparse(import_stmts)  # type: ignore
            + "\n"
            + ast.unparse(function_ast)  # type: ignore
        )
        return main_code
    except Exception:
        return code


def call_method(method, inputs):
    if isinstance(inputs, list):
        inputs = "\n".join(inputs)

    inputs_line_iterator = iter(inputs.split("\n"))

    # Create custom stdin mock with buffer support
    mock_stdin = MockStdinWithBuffer(inputs)

    # sys.setrecursionlimit(10000)

    # @patch('builtins.input', side_effect=inputs.split("\n"))
    @patch("builtins.open", mock_open(read_data=inputs))
    @patch("sys.stdin", mock_stdin)  # Use our custom mock instead of StringIO
    @patch("sys.stdin.readline", lambda *args: next(inputs_line_iterator))
    @patch("sys.stdin.readlines", lambda *args: inputs.split("\n"))
    @patch("sys.stdin.read", lambda *args: inputs)
    # @patch('sys.stdout.write', print)
    def _inner_call_method(_method):
        try:
            return _method()
        except SystemExit:
            pass
        finally:
            pass

    return _inner_call_method(method)


def get_function(compiled_sol, fn_name: str):  # type: ignore
    try:
        assert hasattr(compiled_sol, fn_name)
        return getattr(compiled_sol, fn_name)
    except Exception:
        return


def compile_code(code: str, timeout: int):
    signal.alarm(timeout)
    try:
        tmp_sol = ModuleType("tmp_sol", "")
        exec(code, tmp_sol.__dict__)
        compiled_sol = tmp_sol.Solution() if "class Solution" in code else tmp_sol

        assert compiled_sol is not None
    except Exception:
        compiled_sol = None
    finally:
        signal.alarm(0)

    return compiled_sol


def convert_line_to_decimals(line: str) -> tuple[bool, list[Decimal]]:
    try:
        decimal_line = [Decimal(elem) for elem in line.split()]
    except Exception:
        return False, []
    return True, decimal_line


def get_stripped_lines(val: str):
    # you don't want empty lines to add empty list after splitlines!
    val = val.strip()

    return [val_line.strip() for val_line in val.split("\n")]


def grade_stdio(code: str, all_inputs: list, all_outputs: list, timeout: int):
    signal.signal(signal.SIGALRM, timeout_handler)
    # runtime doesn't interact well with __name__ == '__main__'
    code = clean_if_name(code)

    # we wrap the given code inside another function
    code = make_function(code)
    compiled_sol = compile_code(code, timeout)
    if compiled_sol is None:
        return ([-1] * len(all_outputs), [-1.0] * len(all_outputs))

    method = get_function(compiled_sol, "wrapped_function")
    if method is None:
        return ([-1] * len(all_outputs), [-1.0] * len(all_outputs))

    all_results = []
    all_runtimes = []
    total_execution_time = 0
    first_failure_info = None
    for gt_inp, gt_out in zip(all_inputs, all_outputs):
        signal.alarm(timeout)
        faulthandler.enable()

        prediction = None
        try:
            with Capturing() as captured_output:
                start = time.time()
                call_method(method, gt_inp)
                end_time = time.time()
                total_execution_time += end_time - start
                all_runtimes.append(end_time - start)
                # reset the alarm
            signal.alarm(0)
            prediction = captured_output[0] if captured_output else ""

        except Exception as e:
            signal.alarm(0)
            all_runtimes.append(-1.0)
            if "timeoutexception" in repr(e).lower():
                all_results.append(-3)
                if not first_failure_info:
                    first_failure_info = {"error_code": -3, "error_message": "Time Limit Exceeded"}
                continue
            else:
                all_results.append(-4)
                if not first_failure_info:
                    first_failure_info = {"error_code": -4, "error_message": f"Runtime Error: {e}"}
                continue
        finally:
            signal.alarm(0)
            faulthandler.disable()

        if prediction is None:
            # Should not happen if there was no exception, but as a safeguard.
            all_results.append(-4)  # Runtime error
            if not first_failure_info:
                first_failure_info = {"error_code": -4, "error_message": "Runtime Error: No output produced"}
            continue

        stripped_prediction_lines = get_stripped_lines(prediction)
        stripped_gt_out_lines = get_stripped_lines(gt_out)

        if len(stripped_prediction_lines) != len(stripped_gt_out_lines):
            all_results.append(-2)
            if not first_failure_info:
                first_failure_info = {"error_code": -2, "error_message": "Wrong answer: mismatched output length"}
            continue

        test_case_failed = False
        for stripped_prediction_line, stripped_gt_out_line in zip(stripped_prediction_lines, stripped_gt_out_lines):
            if stripped_prediction_line == stripped_gt_out_line:
                continue

            success, decimal_prediction_line = convert_line_to_decimals(stripped_prediction_line)
            if not success:
                test_case_failed = True
                break
            success, decimal_gtout_line = convert_line_to_decimals(stripped_gt_out_line)
            if not success:
                test_case_failed = True
                break

            if decimal_prediction_line == decimal_gtout_line:
                continue

            test_case_failed = True
            break

        if test_case_failed:
            all_results.append(-2)
            if not first_failure_info:
                first_failure_info = {"error_code": -2, "error_message": "Wrong Answer"}
            continue

        all_results.append(True)

    if first_failure_info:
        print(f"first_failure_info: {first_failure_info}")
        return all_results, all_runtimes

    return all_results, all_runtimes

"""Sandbox backend abstraction for code/command execution."""

import io
import os
import shlex
import tarfile
from abc import ABC, abstractmethod
from dataclasses import dataclass

import docker as docker_sdk

from open_instruct import logger_utils

logger = logger_utils.setup_logger(__name__)


@dataclass
class ExecutionResult:
    """Result from code or command execution."""

    stdout: str
    stderr: str
    exit_code: int


class SandboxBackend(ABC):
    """Abstract interface for code/command execution backends."""

    @abstractmethod
    def start(self) -> None:
        """Initialize the sandbox. Must be called before other operations."""

    @abstractmethod
    def run_command(self, command: str) -> ExecutionResult:
        """Execute a shell command in the sandbox."""

    @abstractmethod
    def write_file(self, path: str, content: str | bytes) -> None:
        """Write a file to the sandbox filesystem."""

    @abstractmethod
    def read_file(self, path: str, binary: bool = False) -> str | bytes:
        """Read a file from the sandbox filesystem."""

    @abstractmethod
    def close(self) -> None:
        """Cleanup sandbox resources."""


class DockerBackend(SandboxBackend):
    """Local Docker backend using the ``docker`` Python SDK.

    Runs code in a Docker container on the local machine.
    Requires Docker to be running and the ``docker`` pip package installed.
    """

    _MAX_OUTPUT_BYTES = 1_000_000

    def __init__(self, image: str = "python:3.12-slim", timeout: int = 1800, mem_limit: str = "4g"):
        """
        Args:
            image: Docker image to use (default: python:3.12-slim)
            timeout: Per-command timeout in seconds (default: 1800 / 30 min)
            mem_limit: Memory limit for the container (default: 4g)
        """
        self._image = image
        self._timeout = timeout
        self._mem_limit = mem_limit
        self._container = None
        self._client = None

    def start(self) -> None:
        logger.info(f"Starting Docker container (image={self._image})")
        if self._client is None:
            self._client = docker_sdk.from_env()
        self._container = self._client.containers.run(
            self._image,
            command="sleep infinity",
            detach=True,
            remove=True,
            mem_limit=self._mem_limit,
            memswap_limit=self._mem_limit,
        )
        logger.info(f"Docker container started: {self._container.short_id}")

    def run_command(self, command: str) -> ExecutionResult:
        if self._container is None:
            raise RuntimeError("Container not started. Call start() first.")

        wrapped = (
            f"timeout --signal=TERM --kill-after=10 {shlex.quote(str(self._timeout))} bash -c {shlex.quote(command)}"
        )
        exit_code, output = self._container.exec_run(["bash", "-c", wrapped], demux=True)
        stdout_raw = (output[0] or b"") if output else b""
        stderr_raw = (output[1] or b"") if output else b""
        stdout = stdout_raw[: self._MAX_OUTPUT_BYTES].decode("utf-8", errors="replace")
        stderr = stderr_raw[: self._MAX_OUTPUT_BYTES].decode("utf-8", errors="replace")
        if exit_code == 124:
            stderr = f"Command timed out after {self._timeout}s.\n" + stderr
        return ExecutionResult(stdout=stdout, stderr=stderr, exit_code=exit_code)

    def write_file(self, path: str, content: str | bytes) -> None:
        if self._container is None:
            raise RuntimeError("Container not started. Call start() first.")

        if isinstance(content, str):
            content = content.encode("utf-8")

        tar_stream = io.BytesIO()
        with tarfile.open(fileobj=tar_stream, mode="w") as tar:
            info = tarfile.TarInfo(name=os.path.basename(path))
            info.size = len(content)
            tar.addfile(info, io.BytesIO(content))
        tar_stream.seek(0)
        self._container.put_archive(os.path.dirname(path) or "/", tar_stream)

    def read_file(self, path: str, binary: bool = False) -> str | bytes:
        if self._container is None:
            raise RuntimeError("Container not started. Call start() first.")

        try:
            tar_chunks, _stat = self._container.get_archive(path)
        except docker_sdk.errors.NotFound:
            raise FileNotFoundError(f"File not found in container: '{path}'") from None
        except docker_sdk.errors.APIError as e:
            raise FileNotFoundError(f"Failed to read file '{path}': {e}") from None

        tar_bytes = b"".join(tar_chunks)
        with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r") as tar:
            member = tar.getmembers()[0]
            extracted = tar.extractfile(member)
            if extracted is None:
                raise IsADirectoryError(f"Path '{path}' is a directory, not a file.")
            content_raw = extracted.read()

        if binary:
            return content_raw
        return content_raw.decode("utf-8", errors="replace")

    def close(self) -> None:
        if self._container is not None:
            cid = self._container.short_id
            logger.info(f"Closing Docker container: {cid}")
            try:
                self._container.stop(timeout=5)
            except Exception as e:
                logger.warning(f"Error stopping container {cid}, attempting kill: {e}")
                try:
                    self._container.kill()
                except Exception as kill_err:
                    logger.warning(f"Error killing container {cid}: {kill_err}")
            self._container = None


def create_backend(backend_type: str, **kwargs) -> SandboxBackend:
    """Factory function to create a sandbox backend.

    Args:
        backend_type: Currently only "docker" is supported.
        **kwargs: Backend-specific arguments.

    Returns:
        SandboxBackend instance (not yet started).
    """
    if backend_type == "docker":
        return DockerBackend(**kwargs)
    else:
        raise ValueError(f"Unknown backend type: {backend_type}. Currently only 'docker' is supported.")

